// Plain text only: external mail is hostile (CLAUDE.md rule 11).
const MAX_TEXT = 8000;
return $input.all().map(({ json }) => {
  const headers = json.headers ?? {};
  return { json: {
    message_id: json.messageId ?? headers['message-id'] ?? null,
    in_reply_to: headers['in-reply-to'] ?? null,
    references: headers['references'] ?? null,
    sender: String(json.from ?? '').toLowerCase(),
    subject: String(json.subject ?? ''),
    body: String(json.textPlain ?? '').slice(0, MAX_TEXT),
  } };
});
